CREATE TYPE "leave_request_status" AS ENUM ('PENDING', 'APPROVED', 'REJECTED', 'CANCELLED');
CREATE TABLE "leave_allowance_settings" ("singleton" boolean PRIMARY KEY DEFAULT true NOT NULL, "annual_working_days" integer DEFAULT 22 NOT NULL, "version" integer DEFAULT 1 NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL, CONSTRAINT "leave_allowance_settings_singleton_check" CHECK ("singleton" = true), CONSTRAINT "leave_allowance_settings_days_check" CHECK ("annual_working_days" BETWEEN 1 AND 366), CONSTRAINT "leave_allowance_settings_version_check" CHECK ("version" > 0));
INSERT INTO "leave_allowance_settings" ("singleton", "annual_working_days") VALUES (true, 22);
CREATE TABLE "leave_requests" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "employee_user_id" text NOT NULL REFERENCES "users"("id") ON DELETE RESTRICT, "start_date" date NOT NULL, "end_date" date NOT NULL, "status" "leave_request_status" DEFAULT 'PENDING' NOT NULL, "private_reason" text, "decision_response" text, "reviewed_by_user_id" text REFERENCES "users"("id") ON DELETE RESTRICT, "decided_at" timestamptz, "cancelled_at" timestamptz, "version" integer DEFAULT 1 NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL, CONSTRAINT "leave_requests_date_order_check" CHECK ("end_date" >= "start_date"), CONSTRAINT "leave_requests_private_reason_length_check" CHECK ("private_reason" IS NULL OR char_length("private_reason") <= 1000), CONSTRAINT "leave_requests_response_length_check" CHECK ("decision_response" IS NULL OR char_length("decision_response") <= 1000), CONSTRAINT "leave_requests_version_check" CHECK ("version" > 0));
CREATE INDEX "leave_requests_employee_status_dates_idx" ON "leave_requests" ("employee_user_id", "status", "start_date", "end_date");
CREATE INDEX "leave_requests_status_created_idx" ON "leave_requests" ("status", "created_at");
